"""Exercise 1302 figure 390 and each printed comparison in 1303, page 339."""
import argparse
import json
from math import cos, radians, sin, sqrt
from polygon_similarity_intro import entry, house, pair, rectangle, scaled
from rotated_circles_lines import diagram
from vector_scaling import BOOK, ROOT

OUT = ROOT / 'geometry-course/textbook/data/polygon-similarity-choices.json'


def figure_390():
    # AB, BC, CD, DA turn by 95°, 90°, 75°, 100° in this traversal.
    c = (4 + 2*cos(radians(95)), 2*sin(radians(95)))
    u = (cos(radians(185)), sin(radians(185)))
    v = (cos(radians(80)), sin(radians(80)))
    t = (v[0]*c[1] - v[1]*c[0]) / (u[0]*v[1] - u[1]*v[0])
    return {'A': (0, 0), 'B': (4, 0), 'C': c, 'D': (c[0]+t*u[0], c[1]+t*u[1])}


def quadrilaterals():
    points = figure_390()
    return entry(1302, None, [339],
        'На рисунке 390 сравни два четырёхугольника. У первого стороны по обходу равны 2a, 2b, 2c, 2d, у второго — 3a, 3b, 3c, 3d. Учти и угловые отметки. Подобны ли эти четырёхугольники?',
        'Вершины A, B, C соответствуют A₁, B₁, C₁: в обеих фигурах углы при них равны 80°, 85°, 90°. Оба недостающих угла равны 360°−80°−85°−90°=105°. При том же порядке обхода отношения сторон первой фигуры к соответствующим сторонам второй равны 2a/(3a)=2b/(3b)=2c/(3c)=2d/(3d)=2/3. Условия подобия выпуклых многоугольников выполнены. В обратном направлении коэффициент равен 3/2.',
        [('Сопоставь соседние вершины', 'Начни с двух соседних отмеченных углов A и B. Следом по обходу стоит прямой угол C. На второй фигуре считай в соответствующем порядке.', 'Одинаковый поворот рисунков на странице не входит в условия подобия. Ищи совпадающие углы и соседние стороны.'),
         ('Восстанови угол D', 'Сумма четырёх внутренних углов выпуклого четырёхугольника 360°. Вычти из неё 80°, 85° и 90°. Для D′ получается то же значение.', 'У треугольника сумма 180°, а в этом упражнении фигурой служит четырёхугольник.'),
         ('Повтори с другим коэффициентом', 'На третьем авторском рисунке стороны копии вдвое больше исходных. Сторона AB равна 4. Вычисли длину A′B′ и объясни, почему поворот копии не меняет ответа.', 'Коэффициент 3/2 относится к исходному рисунку 390. Используй масштаб 2 из подписи нового построения.')],
        [scaled('Углы 80°, 85° и 90° и масштаб 3/2', points,1.5,1.5,72),scaled('Найди угол при D и D′',points,1.5,1.5,-25),scaled('Новая пара с масштабом 2',points,2,2,30)],
        [('Сколько градусов в угле D?','105','360−80−85−90=105.'),('Какова длина A′B′ при новом масштабе 2 и AB=4?','8','4·2=8.')],
        'Для подобных выпуклых многоугольников нужны равные соответствующие углы и единая пропорция соответствующих сторон.',
        'Сохраняй одно направление сравнения для всех четырёх отношений. В печатном рисунке буквы с индексом 1 отвечают штрихам модели.',
        'Независимый чертёж воспроизводит четыре угла и отношения длин рисунка 390. Третья модель иллюстрирует новый масштаб.',refs=[131])


def regular(n, r=1):
    return {chr(65+i):(r*cos(radians(90+360*i/n)), r*sin(radians(90+360*i/n))) for i in range(n)}


def juxtaposed(title, first, second):
    end = max(x for x,y in first.values())
    shift = end-min(x for x,y in second.values())+1.2
    right = {k+'′':(x+shift,y) for k,(x,y) in second.items()}
    sides=[]
    for shape in (list(first), list(right)):
        sides.extend((shape[i],shape[(i+1)%len(shape)]) for i in range(len(shape)))
    return diagram(title,{**first,**right},sides)


def compare(part):
    equilateral={'A':(-1,0),'B':(1,0),'C':(0,sqrt(3))}
    obtuse={'A':(-2,0),'B':(2,0),'C':(0,1)}
    isosceles={'A':(-1,0),'B':(1,0),'C':(0,1)}
    pent=house()
    if part=='а':
        source='остроугольный треугольник и тупоугольный треугольник'
        proof='Нет. У тупоугольного треугольника один угол больше 90°. Соответствующий ему угол первого треугольника должен был бы равняться ему, но все углы остроугольного треугольника меньше 90°. Поворот и изменение размеров сохраняют каждый угол.'
        scenes=[juxtaposed('Три острых угла и один тупой угол',equilateral,obtuse),juxtaposed('В первом треугольнике углы по 60°',equilateral,obtuse),scaled('Повтор: увеличенная копия острого треугольника',equilateral,2,2,24)]
        steps=[('Найди угол, которому нет пары','Осмотри вершину C′ второго треугольника: стороны её угла расходятся шире прямого угла. Есть ли такой угол в первой фигуре?','Треугольники имеют одинаковое число вершин, но это ещё не обеспечивает подобия.'),
               ('Проверь конкретную пару','У равностороннего треугольника слева все углы по 60°. Сколько у него углов больше 90°?','Тупой угол строго больше 90°.'),
               ('Смени второй треугольник','В третьей модели обе фигуры равносторонние, вторая увеличена и повёрнута. Найди величину угла при C′.','Умножение длины стороны на 2 не удваивает число градусов.')];checks=[('Сколько тупых углов у левого треугольника?','0','Все три угла равны 60°.'),('Сколько градусов в C′ увеличенной копии?','60','Равносторонний треугольник имеет три равных угла.') ]
    elif part=='б':
        source='равносторонний треугольник и равнобедренный треугольник, у которого не все стороны равны'
        proof='Нет. Если все три стороны у первого равны, умножение каждой стороны на один и тот же коэффициент даст три равные стороны и у второго. В условии второй треугольник равнобедренный, но не равносторонний. Эти свойства несовместимы с подобием.'
        scenes=[juxtaposed('Три равные стороны и только две равные',equilateral,isosceles),juxtaposed('Сравни вершины C и C′',equilateral,isosceles),scaled('Повтор: обе фигуры равносторонние',equilateral,3,3,-24)]
        steps=[('Проследи равенства сторон','У первого треугольника три стороны одной длины. После умножения всех трёх на k>0 они снова равны между собой.','Уточнение про неравносторонний второй треугольник существенно.'),
               ('Проверь один угол на модели','Правый пример выбран равнобедренным с прямым углом C′. Левый треугольник равносторонний. Чему равен его угол C?','У равнобедренного треугольника не обязаны быть равны все три угла.'),
               ('Убери ограничение и повтори','В третьей паре обе фигуры равносторонние. При исходной стороне 2 и масштабе 3 вычисли сторону копии.','Число 3 здесь служит коэффициентом нового примера.')];checks=[('Сколько градусов у вершины C равностороннего треугольника?','60','180/3=60.'),('Чему равна сторона увеличенного треугольника?','6','2·3=6.') ]
    elif part=='в':
        source='прямоугольник и квадрат'
        proof='Да, если сам прямоугольник является квадратом. Квадрат — частный случай прямоугольника. Любые два квадрата подобны: углы прямые и отношения всех соответствующих сторон равны. Если соседние стороны прямоугольника различны, один множитель не сможет сделать их равными.'
        scenes=[scaled('Квадрат как частный случай прямоугольника',rectangle(2,2),1.5,1.5,12),juxtaposed('Прямоугольник 4×2 и квадрат 2×2',rectangle(4,2),rectangle(2,2)),scaled('Два новых квадрата',rectangle(3,3),2,2,-13)]
        steps=[('Прочитай вопрос о возможности','Достаточно предъявить допустимую пару. Возьми прямоугольник с равными соседними сторонами и второй квадрат.','Само слово «прямоугольник» допускает квадрат.'),
               ('Отдели невозможную пару','У прямоугольника 4×2 вычисли отношение длинной стороны к короткой. У квадрата оно равно 1.','Четырёх прямых углов для подобия двух произвольных прямоугольников недостаточно.'),
               ('Повтори с другими сторонами','В третьей схеме исходный квадрат имеет сторону 3, а коэффициент увеличения равен 2. Найди сторону его образа.','Обе координаты меняются с одинаковым коэффициентом.')];checks=[('Каково отношение 4 к 2?','2','4/2=2.'),('Чему равна сторона копии квадрата со стороной 3?','6','2·3=6.') ]
    elif part=='г':
        source='два прямоугольника'
        proof='Да. Например, прямоугольники 3×2 и 6×4 подобны с коэффициентом 2 для второго относительно первого. У них равны все углы и совпадают отношения длинных и коротких сторон. В общем случае нужно совместить длинные стороны с длинными, короткие с короткими и проверить один масштаб, или сравнить отношения длины к ширине.'
        scenes=[scaled('Прямоугольники 3×2 и 6×4',rectangle(3,2),2,2,5),juxtaposed('Новая пара 3×2 и 6×2',rectangle(3,2),rectangle(6,2)),scaled('Прямоугольники 4×3 и 12×9',rectangle(4,3),3,3,16)]
        steps=[('Предъяви возможную пару','В первой схеме стороны правой фигуры обе вдвое больше соответствующих сторон левой. Сравни четыре прямых угла.','Вопрос «могут ли» допускает, что некоторые другие пары не подобны.'),
               ('Проверь контрпример','У фигур 3×2 и 6×2 высоты одинаковы. Найди отношение высоты второй к высоте первой и сравни с отношением длин оснований.','Если сравниваешь вторую фигуру с первой, дели вторую длину на первую и для высоты, и для основания.'),
               ('Проверь повёрнутую пару','В третьей модели исходный прямоугольник 4×3, итоговый 12×9. Назови их общий коэффициент от первого ко второму.','Наклон сторон на экране не меняет длин.')];checks=[('Чему равно отношение высот 2 и 2?','1','2/2=1, а основания имеют отношение 2.'),('Каков общий коэффициент для 4×3 и 12×9?','3','12/4=9/3=3.') ]
    elif part=='д':
        source='два пятиугольника'
        proof='Да. Возьми любой выпуклый пятиугольник и увеличь все расстояния в два раза. У получившихся пятиугольников соответствующие углы равны, отношения всех пяти пар сторон равны 2. Этого примера достаточно для возможности. Совпадение только числа вершин у произвольной пары пятиугольников такого вывода не даёт.'
        scenes=[scaled('Увеличенный пятиугольник',pent,2,2,8),scaled('Горизонтальное растяжение того же пятиугольника',pent,2,1),scaled('Два правильных пятиугольника',regular(5),3,3,12)]
        steps=[('Назови соответствующие вершины','В первой паре обойди A,B,C,D,E и A′,B′,C′,D′,E′. Проследи, как изменились все пять сторон.','Увеличение должно действовать на всю фигуру одинаково.'),
               ('Проверь неподходящее изменение','Во второй модели горизонтальный размер удвоен, а высота осталась прежней. Каков коэффициент для вертикальной стороны BC?','Одного удвоившегося основания недостаточно, если высота не изменилась.'),
               ('Повтори на другой форме','Третий исходный пятиугольник правильный. Сколько у увеличенной копии соответствующих ему сторон?','Масштаб 3 относится к длинам, а не к числу вершин и сторон.')];checks=[('Чему равно отношение длины B′C′ к BC при неизменённой высоте?','1','Вертикальная сторона сохранила длину.'),('Сколько сторон у увеличенного пятиугольника?','5','Коэффициент подобия не меняет число сторон.') ]
    else:
        source='шестиугольник и пятиугольник'
        proof='Нет. Отображение подобия сохраняет вершины и их порядок по границе выпуклого многоугольника. Шести различным вершинам должны отвечать шесть различных вершин, а у пятиугольника их только пять. Никакой выбор масштаба не изменит это число.'
        scenes=[juxtaposed('Правильные шестиугольник и пятиугольник',regular(6),regular(5)),juxtaposed('Посчитай вершины по порядку',regular(6,1.5),regular(5,.8)),scaled('Повтор: два шестиугольника',regular(6),2,2,14)]
        steps=[('Сосчитай изменения направления','Обойди обе границы. У первого многоугольника шесть вершин, у второго пять.','Начальную вершину при возвращении к ней считай только один раз.'),
               ('Проверь число несовпавших вершин','Если попытаться связать пять различных вершин второго пятиугольника с пятью вершинами шестиугольника, сколько вершин первого останутся без пары?','Совмещать образы двух разных вершин в одной нельзя при положительном коэффициенте.'),
               ('Повтори при том же числе вершин','В третьей модели обе фигуры правильные шестиугольники. Сколько соответствующих пар вершин можно указать, обходя границы?','Само число вершин здесь позволяет сопоставление, а правильность фигур обеспечивает совпадение углов и пропорциональность сторон.')];checks=[('Сколько вершин первого многоугольника останется без пары?','1','6−5=1.'),('Сколько пар вершин у двух подобных шестиугольников?','6','Каждой из шести вершин отвечает одна вершина.') ]
    return entry(1303,part,[339],f'Могут ли быть подобными {source}? Обоснуй возможность примером или докажи невозможность для всех таких пар.',
        proof,steps,scenes,checks,'Для ответа «да» достаточно предъявить одну подходящую пару. Для ответа «нет» найди условие подобия, которое не может выполниться ни у одной такой пары.',
        'Сначала обрати внимание на условия для всех фигур указанного вида, затем проверь возможность или невозможность соответствия.',
        'Сопоставляй вершины по порядку. Название каждой модели указывает, какие фигуры и какое изменение рассматриваются.',refs=[130,131])


if __name__=='__main__':
    parser=argparse.ArgumentParser()
    parser.add_argument('--check',action='store_true')
    rows=[quadrilaterals(),*[compare(part) for part in 'абвгде']]
    raw=json.dumps({'bookId':BOOK,'lessons':rows},ensure_ascii=False,separators=(',',':'))+'\n'
    if parser.parse_args().check:assert OUT.read_text()==raw
    else:OUT.write_text(raw)
